def specialFilter(nums):
    import re
    count = 0
    for num in nums:
        s = str(num)
        if re.fullmatch(r'[-+]?\d+', s):
            first = int(s[0])
            last = int(s[-1])
            if first in {1, 3, 5, 7, 9} and last in {1, 3, 5, 7, 9} and int(s) > 10:
                count += 1
    return count
